const input = $input.first()?.json?.body || $input.first()?.json || {};
const options = input.options || {};
const raw = options.rawValues || {};
const sourcePages = Array.isArray(input.batchItems) ? input.batchItems : [];
const fallbackPages = String(raw.storybookContent || input.storybookContent || '')
  .split(/\r?\n+/)
  .map((text, index) => ({ page: index + 1, text: text.trim() }))
  .filter((item) => item.text);
const pages = (sourcePages.length ? sourcePages : fallbackPages).slice(0, 20);
if (pages.length < 2) throw new Error('A picture book needs at least 2 pages. Put one page on each line.');
const title = String(input.storybookTitle || raw.storybookTitle || 'My Picture Book').trim();
const style = String(input.storybookStyle || raw.storybookStyle || options.imageStyle || 'Watercolor Picture Book').trim();
const grade = String(input.storybookGrade || raw.storybookGrade || 'Grade 2 (7-8 years)').trim();
const width = Math.max(512, Math.min(2048, Number(input.width) || 1280));
const height = Math.max(512, Math.min(2048, Number(input.height) || 720));
const baseSeed = Math.floor(Math.random() * 900000000000000);
const negative = String(input.negative_prompt || 'blurry, low quality, watermark, logo, misspelled text, unreadable text, photorealistic, 3d, inconsistent character, extra limbs, cropped');
const workflowTemplate = {
  '1': { inputs: { unet_name: 'z_image_turbo_bf16.safetensors', weight_dtype: 'default' }, class_type: 'UNETLoader' },
  '2': { inputs: { vae_name: 'ae.safetensors' }, class_type: 'VAELoader' },
  '3': { inputs: { clip_name: 'qwen_3_4b.safetensors', type: 'lumina2', device: 'default' }, class_type: 'CLIPLoader' },
  '4': { inputs: { shift: 3, model: ['1', 0] }, class_type: 'ModelSamplingAuraFlow' },
  '5': { inputs: { width, height, batch_size: 1 }, class_type: 'EmptySD3LatentImage' },
  '11': { inputs: { lora_name: 'poppy.safetensors', strength_model: 0.8, strength_clip: 1, model: ['4', 0], clip: ['3', 0] }, class_type: 'LoraLoader' },
  '6': { inputs: { text: '', clip: ['11', 1] }, class_type: 'CLIPTextEncode' },
  '7': { inputs: { text: negative, clip: ['11', 1] }, class_type: 'CLIPTextEncode' },
  '8': { inputs: { seed: baseSeed, steps: 15, cfg: 1.5, sampler_name: 'euler', scheduler: 'simple', denoise: 1, model: ['11', 0], positive: ['6', 0], negative: ['7', 0], latent_image: ['5', 0] }, class_type: 'KSampler' },
  '9': { inputs: { samples: ['8', 0], vae: ['2', 0] }, class_type: 'VAEDecode' },
  '10': { inputs: { filename_prefix: 'Storybook', images: ['9', 0] }, class_type: 'SaveImage' }
};
const stylePrompt = style.toLowerCase().includes('watercolor') || style.includes('水彩')
  ? 'Oliver Jeffers-inspired loose watercolor and black colored-pencil sketch, translucent low-saturation gray-blue, dusty pink, sage, ochre and lavender washes, warm off-white paper, playful imperfect hand-drawn linework'
  : style.toLowerCase().includes('paper') || style.includes('剪纸')
    ? 'layered handmade paper-cut collage, tactile paper fibers, soft child-friendly shapes, warm editorial storybook composition'
    : 'friendly premium children picture-book illustration, simple rounded shapes, warm soft colors and expressive hand-drawn details';
const characterBible = 'Poppy is always the same small pink cloud character: rounded scalloped cloud body, two solid black dot eyes without pupils, tiny curved smile, two thin black legs and oval black feet. Keep her proportions, face and colors identical on every page.';
return pages.map((page, index) => {
  const pageNo = Number(page.page) || index + 1;
  const text = String(page.text || '').trim();
  const workflow = JSON.parse(JSON.stringify(workflowTemplate));
  const exactText = pageNo === 1 ? `${title}\n${text}` : text;
  workflow['6'].inputs.text = [
    `A polished landscape children's picture-book page, page ${pageNo} of ${pages.length}, for ${grade}.`,
    stylePrompt + '.',
    characterBible,
    `Story action and scene: ${text}.`,
    'Sparse free-floating composition with at least 50 percent calm negative space. Flat full-page artwork, subtle pencil marks and watercolor splashes, no mockup, no book photographed in a scene.',
    `Render only this exact English page text, clearly and legibly in a playful handwritten black font: "${exactText}".`,
    `Put a very small plain page number ${pageNo} at the bottom center. Do not add any other words.`
  ].join(' ');
  workflow['8'].inputs.seed = baseSeed + pageNo;
  workflow['10'].inputs.filename_prefix = `Storybook_${title.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(0, 32)}_P${String(pageNo).padStart(2, '0')}`;
  return { json: {
    page: pageNo,
    title: `${title} · Page ${pageNo}`,
    pageText: text,
    comfyuiUrl: 'https://vcbj5meqyp1y7ifw-8188.container.x-gpu.com',
    comfyuiPayload: { prompt: workflow }
  } };
});

const responses = $input.all();
const prepared = $('准备绘本分页任务').all();
const assets = responses.map((item, index) => {
  const meta = prepared[index]?.json || {};
  const response = item.json || {};
  const executionId = response.prompt_id || response.id;
  if (!executionId) throw new Error(`ComfyUI did not return a task id for page ${meta.page || index + 1}`);
  return {
    executionId,
    comfyuiUrl: meta.comfyuiUrl,
    workflowType: 'image',
    status: 'submitted',
    page: meta.page || index + 1,
    title: meta.title || `Picture Book · Page ${index + 1}`,
    pageText: meta.pageText || ''
  };
});
assets.sort((a, b) => a.page - b.page);
return [{ json: { success: true, status: 'submitted', pageCount: assets.length, assets } }];
